status.p:
Some external object models do not provide information about ID attributes;
          in such cases this function will always return an empty sequence. In particular, this is
          true when the object model is a DOM.

div.p:
This function returns a sequence obtained by successive evaluations of the $step
            function. Each call on $step gets two arguments, (a) the current item in the sequence,
            and (b) the 1-based position in the sequence. The first item in the sequence is $start.

pre.code:
declare namespace StreamSource = "java:javax.xml.transform.stream.StreamSource";
declare namespace map = "http://www.w3.org/2005/xpath-functions/map";
StreamSource:new() => saxon:object-map() => map:keys() => sort()

declare namespace saxon = "http://saxon.sf.net/"; 

<out>{ 
let $q1 := "declare variable $x external; declare variable $y external; <z>{$x + $y + .}</z&>" 
    return saxon:query(saxon:compile-query($q1), 4, (<x>3</x>, <y>2</y>)) 
}</out>

let $bookDecl := saxon:schema('element declaration', QName('', 'book')) 
return if ($bookDecl('type definition')('variety') = 'element-only') 
       then ... 
       else ...

declare namespace saxon="http://saxon.sf.net/"; 
declare namespace xsl="http://www.w3.org/1999/XSL/Transform"; 

<out>{ 
let $x := <a><b/><c>content</c><?pi?><!--comment--></a>
return saxon:serialize($x, <xsl:output method="xml" 
                                 omit-xml-declaration="yes"
                                 indent="yes" 
                                 saxon:indent-spaces="1"/>) 
}</out>

let $splitter := saxon:compile-stylesheet( 
  <xsl:stylesheet xmlns:xsl="http://www.w3.org/1999/XSL/Transform" 
                     version="2.0"> 
    <xsl:template match="customer"> 
      <xsl:result-document href="{{@id}}.xml"> 
        <xsl:copy-of select="."/> 
      </xsl:result-document> 
    </xsl:template>
  </xsl:stylesheet>) 
let $results := 
  document { 
    <customers>{ //customer[location="Scotland"] }</customers> 
  } 
return saxon:transform($splitter, $results)

div.p:
For example, Saxon would normally build an index to evaluate an expression such as
              //person[@ssn=$ssn]. But there are cases where this is not the best
            strategy, for example:

pre.code:
declare namespace saxon = "http://saxon.sf.net/"; 

<out>{ 
   let $q1 := "declare variable $x external; declare variable $y external; <z>{$x + $y + .}</z>" 
   let $qry := saxon:xquery($q1)
   return $qry(4, map{xs:QName('x'): 3, xs:QName('y'): 2})
}</out>
